
-- Q1. what is total revenue generated by male v/s female customers ? 
select gender ,sum(purchase_amount) as revenue from customer_data group by gender;

-- Q2] Which customers used a discount but still spent more than an average purchase amount ?
select customer_id , purchase_amount 
from customer_data 
where discount_applied = 'Yes' and purchase_amount > (select avg(purchase_amount) from customer_data);

-- Q3] which are the top 5 products with the highest average review rating ? 
select item_purchased , round(avg(review_rating),2) as 'Average Review Rating' from customer_data group by item_purchased order by avg(review_rating )desc limit 5 ;

-- Q4] Compare the average purchase amount between standard and express shipping ? 
select round( avg(purchase_amount ),2) as 'Average Purchase Amount', shipping_type 
from customer_data 
where shipping_type in ('Express' , 'Standard')
group by shipping_type; 

-- Q5] Do subscribed customers spend more ? Compare average spend and total revenue between subscribers and non-subscribers ? 
select subscription_status ,count(customer_id) as total_customers , round(avg(purchase_amount),2) as avg_spent , sum(purchase_amount) as Total_Revenue 
from customer_data
group by  subscription_status 
order by total_revenue desc ; 

-- ***  Q6] Which 5 products have the highest percentge of purchases with discounts applied? ***
-- Here we are finding that which product is heavily depend on discounts.
select item_purchased , 
round(100 * sum(case when discount_applied = 'Yes' then 1 else 0 end)/count(*),2) as Percentage_of_discount 
from customer_data 
group by item_purchased
order by Percentage_of_discount desc limit 5 ;

-- Q7] Segment customers into new , returning and loyal based on their total number of previous purchases , and show the count of each segment ? 
-- 1 --> new
-- 2 -10  --> returning 
-- >11  --> Loyal 

with customer_type as 
(
select customer_id , previous_purchases,
case
	when previous_purchases =1 then 'new'
	when previous_purchases between 2 and 10 then 'returning'
	else 'Loyal'
    end as customer_segment
from customer_data
)
select customer_segment , count(*) as 'No. of Customers'
from customer_type
group by customer_segment;

-- Q8] What are the top 3 most purchased products within each category ? 
-- We use a row_number() instead of rank() and dense_Rank() because we want diffrent numbers at every row.
with item_counts as(
select category , item_purchased ,count(customer_id) as total_order, 
row_number() over(partition by category order by count(customer_id) desc )  as item_rank
from customer_data
group by category , item_purchased ) 

select item_rank , category , item_purchased , total_order 
from item_counts 
where item_rank<=3;


-- Q9] Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe ? 
-- Here we want to see that the subscription plan is good or not ?
select subscription_status , count(customer_id) as repeat_buyers 
from customer_data
where previous_purchases > 5
group by subscription_status;

-- Q10] What is revenue contribution of each age group ? 
select age_group , sum(purchase_amount) as Total_Revenue
from customer_data
group by age_group
order by Total_Revenue  desc;
    

